#include <pthread.h>
#include <stdio.h>

#define N 1          /* capacity 1, as in the worked example */
#define NITEMS 5

static int buf[N];
static int count = 0, in = 0, out = 0;
static pthread_mutex_t lk = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t not_full  = PTHREAD_COND_INITIALIZER;  /* xv6: sleep(&not_full, &lk) */
static pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;  /* xv6: sleep(&not_empty, &lk) */

void *producer(void *arg) {
    (void)arg;
    for (int item = 1; item <= NITEMS; item++) {
        pthread_mutex_lock(&lk);
        while (count == N)                      /* re-check on wakeup: never trust a stale test */
            pthread_cond_wait(&not_full, &lk);   /* atomically: unlock lk, block, relock on return */
        buf[in] = item; in = (in + 1) % N; count++;
        pthread_cond_signal(&not_empty);         /* xv6: wakeup(&not_empty) -- lk still held here */
        pthread_mutex_unlock(&lk);
    }
    return NULL;
}

void *consumer(void *arg) {
    (void)arg;
    int total = 0;
    for (int i = 0; i < NITEMS; i++) {
        pthread_mutex_lock(&lk);
        while (count == 0)
            pthread_cond_wait(&not_empty, &lk);
        int item = buf[out]; out = (out + 1) % N; count--;
        pthread_cond_signal(&not_full);
        pthread_mutex_unlock(&lk);
        total += item;
    }
    printf("consumed %d items, sum = %d\n", NITEMS, total);
    return NULL;
}

int main(void) {
    pthread_t tp, tc;
    pthread_create(&tp, NULL, producer, NULL);
    pthread_create(&tc, NULL, consumer, NULL);
    pthread_join(tp, NULL);
    pthread_join(tc, NULL);
    return 0;
}
